"use client";

import { useSession, signOut } from "next-auth/react";

export default function ProfilePage() {
  const { data: session, status } = useSession();

  if (status === "loading") return <p className="text-white text-center mt-20">Laden...</p>;
  if (!session) return <p className="text-white text-center mt-20">Log in om je profiel te zien.</p>;

  return (
    <div className="min-h-screen bg-black flex items-center justify-center p-6">
      <div className="bg-gray-900 rounded-3xl shadow-2xl w-full max-w-md p-8 border border-gray-700">
        
        {/* Avatar / Header */}
        <div className="flex flex-col items-center mb-6">
          <div className="w-24 h-24 rounded-full bg-gray-700 flex items-center justify-center text-white text-4xl font-bold">
            {session.user?.email.charAt(0).toUpperCase()}
          </div>
          <h2 className="mt-4 text-2xl font-bold text-white">{session.user?.email}</h2>
          <p className="text-gray-400 mt-1 capitalize">Role: {session.user?.role}</p>
        </div>

        {/* Profile Info */}
        <div className="space-y-4 text-white">
          <div className="flex justify-between border-b border-gray-700 pb-2">
            <span className="text-gray-400">Email</span>
            <span className="font-medium">{session.user?.email}</span>
          </div>

          <div className="flex justify-between border-b border-gray-700 pb-2">
            <span className="text-gray-400">Role</span>
            <span className="font-medium capitalize">{session.user?.role}</span>
          </div>

          <div className="flex justify-between border-b border-gray-700 pb-2">
            <span className="text-gray-400">Lid sinds</span>
            <span className="font-medium">{new Date(session.user?.createdAt || Date.now()).toLocaleDateString()}</span>
          </div>
        </div>

        {/* Buttons */}
        <div className="mt-6 flex flex-col gap-3">
          <button
            onClick={() => alert("Bewerk Profiel feature komt hier")}
            className="w-full p-3 rounded-xl border border-white text-white font-semibold hover:bg-white hover:text-black transition"
          >
            Bewerk Profiel
          </button>
          <button
            onClick={() => signOut({ callbackUrl: "/auth/signin" })}
            className="w-full p-3 rounded-xl bg-white text-black font-semibold hover:bg-gray-300 transition"
          >
            Uitloggen
          </button>
        </div>
      </div>
    </div>
  );
}